from typing import Sequence

def is_admitted(profile: Sequence[int], vector: Sequence[int]) -> bool:
    if len(profile) != len(vector):
        return False
    if any(p <= 0 for p in profile) or any(a > b for a, b in zip(profile, profile[1:])):
        raise ValueError("profile must be positive and nondecreasing")
    return all(1 <= x <= p for x, p in zip(sorted(vector), profile))

if __name__ == "__main__":
    P = (2, 5, 7, 10)
    for x in [(9, 1, 6, 4), (11, 1, 2, 3)]:
        print(x, "admitted:", is_admitted(P, x))

from typing import Sequence, Tuple

def delete_rank(profile: Sequence[int], ordered: Sequence[int], rank: int) -> Tuple[tuple[int, ...], tuple[int, ...]]:
    if list(ordered) != sorted(ordered):
        raise ValueError("vector must be sorted")
    if not all(1 <= x <= p for x, p in zip(ordered, profile)):
        raise ValueError("vector is not admitted")
    return (tuple(profile[:rank]) + tuple(profile[rank+1:]),
            tuple(ordered[:rank]) + tuple(ordered[rank+1:]))

if __name__ == "__main__":
    print(delete_rank((2, 5, 7, 10), (1, 4, 6, 9), 2))

from itertools import product
from typing import Optional, Sequence

def short_kernel_vector(A: Sequence[Sequence[int]], q: int, B: int) -> Optional[tuple[int, ...]]:
    n = len(A[0]) if A else 0
    seen: dict[tuple[int, ...], tuple[int, ...]] = {}
    for u in product(range(-B, B + 1), repeat=n):
        s = tuple(sum(a*x for a, x in zip(row, u)) % q for row in A)
        if s in seen and seen[s] != u:
            return tuple(x-y for x, y in zip(u, seen[s]))
        seen[s] = u
    return None

if __name__ == "__main__":
    A = ((1, 2, 3), (2, 1, 1))
    print(short_kernel_vector(A, 5, 4))

